(()=>{'use strict';const logo='data:image/jpeg;base64,';const get=async p=>{const r=await fetch(p,{cache:'no-store'});if(!r.ok)throw new Error(p);return(await r.text()).trim()};const decode=async(p,n)=>{let b='';for(let i=1;i<=n;i++)b+=await get(`${p}.${i}.b64`);const s=atob(b),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);return new TextDecoder().decode(u)};(async()=>{try{document.querySelectorAll('[data-brand-logo]').forEach(i=>i.src=logo);const st=document.createElement('style');st.textContent=await decode('styles',2);document.head.appendChild(st);document.querySelectorAll('.topbar,.hero,.workspace,.footer').forEach(e=>e.style.visibility='visible');(0,eval)(await decode('app',6));}catch(e){console.error(e);document.body.innerHTML='<main style="max-width:720px;margin:80px auto;padding:28px;font-family:sans-serif"><h1>프로그램 파일을 불러오지 못했습니다.</h1><p>새로고침하거나 네트워크 연결을 확인해 주세요.</p></main>'}})()})();